effect.shader:
// globais do Node ligados ao motor (tools/nodevideo/ligar_globais.py)
#define _viewport_ratio acProporcaoDoNode
vec3 u_xlat0;
vec4 u_xlat1;
bvec2 u_xlatb2;
vec4 u_xlat3;
vec4 u_xlat4;
vec4 u_xlat5;
vec2 u_xlat12;
float u_xlat18;
void main()
{
    u_xlat0.xy = acScreenNorm.xy + vec2(-0.5, -0.5);
    u_xlat12.xy = u_xlat0.xy * vec2(_viewport_ratio.x, _viewport_ratio.y);
    u_xlat0.xy = (int(_keep_aspect) != 0) ? u_xlat0.xy : u_xlat12.xy;
    u_xlat0.xy = u_xlat0.xy + u_xlat0.xy;
    u_xlat1 = texture(inputImg, acScreenNorm.xy);
    u_xlat0.x = dot(u_xlat0.xy, u_xlat0.xy);
    u_xlat0.x = (-_amount) * u_xlat0.x + 1.0;
    u_xlat0.xyz = u_xlat0.xxx * u_xlat1.xyz;
    if(int(_use_inner_mask) != 0) {
        u_xlatb2.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat3.xyz = (u_xlatb2.x) ? vec3(1.0, 0.0, 1.0) : u_xlat0.xyz;
        u_xlat3.w = 1.0;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat1 = u_xlat1 * u_xlat5;
        u_xlat1 = u_xlat3 * u_xlat4 + u_xlat1;
        u_xlat18 = u_xlat4.x * u_xlat1.w;
        fragColor.w = (u_xlatb2.y) ? u_xlat18 : u_xlat1.w;
        fragColor.xyz = u_xlat1.xyz;
    } else {
        fragColor.xyz = u_xlat0.xyz;
        fragColor.w = 1.0;
    }
    return;
}
